 /// The shared maintenance core: drive one backfill batch (no-op once
 /// Complete), then apply `mutate` to the directory and persist it with the
 /// current live count. Called only from the recency-affecting funnels.
+enum DirectoryMutation<'a> {
+    Upsert {
+        conversation_id: &'a [u8],
+        updated_at_ms: u64,
+    },
+    Remove {
+        conversation_id: &'a [u8],
+    },
+}
+
 fn maintain(
     database: &AuthorityDatabase,
     transaction: &mut AuthorityTransaction,
-    mutate: impl FnOnce(&mut Vec<Entry>),
+    mutation: DirectoryMutation<'_>,
 ) -> io::Result<()> {
     backfill_one_batch(database, transaction)?;
-    let (_, mut entries) = load_directory(database, transaction)?;
-    mutate(&mut entries);
-    let live_count = owner_live_count(database, transaction)?;
-    store_directory(database, transaction, live_count, &entries)
+    // Source bytes and the mutation ID both remain owned by this call until
+    // encoding finishes. No borrowed view escapes or becomes cached state.
+    let source = database.entity_get(transaction, &directory_key(transaction)?)?;
+    let mut entries = match source.as_deref() {
+        Some(value) => decode_directory_views(value)?.1,
+        None => Vec::new(),
+    };
+    match mutation {
+        DirectoryMutation::Upsert {
+            conversation_id,
+            updated_at_ms,
+        } => {
+            if let Some(existing) = entries.iter_mut().find(|(_, id)| *id == conversation_id) {
+                existing.0 = updated_at_ms;
+            } else {
+                entries.push((updated_at_ms, conversation_id));
+            }
+            entries.sort_unstable_by(|a, b| b.0.cmp(&a.0).then_with(|| b.1.cmp(a.1)));
+            entries.truncate(MAX_RECENCY_DIRECTORY_ENTRIES);
+        }
+        DirectoryMutation::Remove { conversation_id } => {
+            entries.retain(|(_, id)| *id != conversation_id)
+        }
+    }
+    let count = owner_live_count(database, transaction)?;
+    let encoded = encode_directory_views(count, entries.len(), entries.into_iter());
+    database.entity_put(transaction, directory_key(transaction)?, encoded)
 }

